    return celsius;
}

"""
    Given a particular number of beats in a bar and grouping option, we need to calculate what
    beats are to be considered strong beats. for example in 7/4 time signature, with grouping of
    2,2,3 the strong beats are 1, 3, and 5.

    :param beats_in_bar: integer. The number of beats in a bar.
    :param grouping: list of integers. The beat grouping chosen by the user.
    """
def calculate_strong_beats(beats_in_bar: Any, grouping: Any) -> object {
    strong_beats = [1];
    for beat in grouping {
        strong_beat = strong_beats[-1] + beat;
        if (strong_beat < beats_in_bar) {
            strong_beats.append(strong_beat);
        }
    }
    return strong_beats;
}

"""
    Transcribes dna to rna.

    Args:
        dna (str}: DNA string (whose alphabet contains the symbols 'A', 'C', 'G', and 'T').

    Returns:
        str: rna where 'T' is replaced by 'U'.
    """
def dna_to_rna(dna: Any) -> object {
    rna = dna.replace("T", "U");
    return rna;
}

"""
    Parameters
    ----------
    SEG_label : list
        label list.

    Returns
    -------
    count_list : array

    """
def count_label(SEG_label: Any) -> object {
    (N, S, V, F, Q) = (0, 0, 0, 0, 0);
    for i in range(len(SEG_label)) {
        count_N = SEG_label[i].count('N');
        count_S = SEG_label[i].count('S');
        count_V = SEG_label[i].count('V');
        count_F = SEG_label[i].count('F');
        count_Q = SEG_label[i].count('Q');
        N += count_N;
        S += count_S;
        V += count_V;
        F += count_F;
        Q += count_Q;
    }
    count_list = [N, S, V, F, Q];
    return count_list;
}

